package net.civeira.phylax.features.access.clientidentity.infrastructure.repository;

import java.util.Iterator;
import java.util.List;
import java.util.function.BiFunction;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.features.access.clientidentity.domain.ClientIdentity;
import net.civeira.phylax.features.access.clientidentity.domain.gateway.ClientIdentityCursor;
import net.civeira.phylax.features.access.clientidentity.domain.gateway.ClientIdentityFilter;

class ClientIdentitySlider extends Slider<ClientIdentity> {

  /**
   * @autogenerated SlideGenerator
   */
  private final ClientIdentityCursor cursor;

  /**
   * @autogenerated SlideGenerator
   */
  private final ClientIdentityFilter filter;

  /**
   * @autogenerated SlideGenerator
   */
  private final BiFunction<ClientIdentityFilter, ClientIdentityCursor, Iterator<ClientIdentity>> gateway;

  /**
   * @autogenerated SlideGenerator
   * @param multi
   * @param limit
   * @param gateway
   * @param filter
   * @param cursor
   */
  ClientIdentitySlider(final Iterator<ClientIdentity> multi, final int limit,
      final BiFunction<ClientIdentityFilter, ClientIdentityCursor, Iterator<ClientIdentity>> gateway,
      final ClientIdentityFilter filter, final ClientIdentityCursor cursor) {
    super(multi, limit);
    this.gateway = gateway;
    this.filter = filter;
    this.cursor = cursor;
  }

  /**
   * @autogenerated SlideGenerator
   * @param clientIdentitys
   * @param limit
   * @return
   */
  @Override
  public Iterator<ClientIdentity> next(List<ClientIdentity> clientIdentitys, int limit) {
    ClientIdentity last = clientIdentitys.get(clientIdentitys.size() - 1);
    ClientIdentityCursor cr = this.cursor.withSinceUid(last.getUid()).withLimit(limit);
    return gateway.apply(this.filter, cr);
  }
}
